//! Inline Heroicons SVG library (outline variant, 24 × 24 viewBox).
//!
//! All icons are pure functions: `icon_name(class: &str) -> Html`.
//! Example:  `{ icons::calendar("w-5 h-5 text-indigo-500") }`

use yew::prelude::*;

macro_rules! icon {
    ($name:ident, $path:literal) => {
        pub fn $name(cls: &str) -> Html {
            let cls = cls.to_owned();
            html! {
                <svg class={cls} xmlns="http://www.w3.org/2000/svg"
                     fill="none" viewBox="0 0 24 24"
                     stroke-width="1.5" stroke="currentColor">
                    <path stroke-linecap="round" stroke-linejoin="round" d={$path} />
                </svg>
            }
        }
    };
}

